function stripV(s) { return String(s || "").replace(/^v/i, ""); }

function resolveTag(template, value) {
  const raw = String(value || "");
  if (!raw) return "";
  if (!template || template.indexOf("${") === -1) return raw;
  const m = stripV(raw).match(/^(\d+)\.(\d+)\.(\d+)/);
  if (!m) return raw;
  const rendered = template.replace(/\$\{major\}/g, m[1]).replace(/\$\{minor\}/g, m[2]).replace(/\$\{patch\}/g, m[3]);
  const parts = rendered.split("/tag/");
  if (parts.length < 2) return raw;
  const seg = parts[1].split("/")[0];
  return seg || raw;
}

const out = [];
for (const item of $input.all()) {
  const c = item.json || {};
  if (!c.updateAvailable) continue;
  const uk = c.updateKind || {};
  if (uk.kind !== "tag") continue;
  const link = c.linkTemplate || "";
  const m = link.match(/github\.com\/([^\/]+\/[^\/]+)/);
  const repo = m ? m[1] : "";
  const oldRaw = uk.localValue || "";
  const newRaw = uk.remoteValue || "";
  const oldTag = resolveTag(link, oldRaw);
  const newTag = resolveTag(link, newRaw);
  out.push({ json: {
    container: c.name,
    image: (c.image && c.image.name) || "",
    oldTag: oldTag,
    newTag: newTag,
    oldRaw: oldRaw,
    newRaw: newRaw,
    tagResolved: (oldTag !== oldRaw) || (newTag !== newRaw),
    repo: repo,
    hasRepo: repo.length > 0
  }});
}
return out;

const up = $('Iterate Through Upgrades').item.json;
const rel = $('Retrieve Release Notes').item.json || {};
const cmp = $input.first().json || {};
const MIG = /(migrations?|migrate)\//i;
const diffOk = Array.isArray(cmp.files);
const files = diffOk ? cmp.files : [];
const migFiles = files.filter(function (f) { return MIG.test(f.filename || ""); });

let sql = migFiles.map(function (f) {
  return "--- " + f.filename + " (" + f.status + ") ---\n" + (f.patch || "(patch not returned by API)");
}).join("\n\n");
let truncated = false;
if (sql.length > 18000) { sql = sql.slice(0, 18000); truncated = true; }
if (!sql) { sql = diffOk ? "(no migration files changed between these tags)" : "(migration diff could NOT be fetched - nothing was inspected)"; }

const addedOnly = migFiles.map(function (f) {
  return String(f.patch || "").split("\n").filter(function (l) {
    return l.charAt(0) === "+" && l.slice(0, 3) !== "+++";
  }).join("\n");
}).join("\n");

const DESTRUCTIVE = [
  { re: /\bDELETE\s+FROM\b/i, label: "DELETE FROM" },
  { re: /\bDROP\s+COLUMN\b/i, label: "DROP COLUMN" },
  { re: /\bDROP\s+TABLE\b/i, label: "DROP TABLE" },
  { re: /\bTRUNCATE\b/i, label: "TRUNCATE" },
  { re: /\bRAISE\s+EXCEPTION\b/i, label: "RAISE EXCEPTION" }
];
const REWRITE = [
  { re: /\bUPDATE\s+\"?[A-Za-z_]/i, label: "UPDATE" },
  { re: /\bALTER\s+TABLE\b/i, label: "ALTER TABLE" },
  { re: /\bRENAME\s+(TO|COLUMN|CONSTRAINT)\b/i, label: "RENAME" }
];

const hits = [];
DESTRUCTIVE.forEach(function (d) { if (d.re.test(addedOnly)) hits.push(d.label); });
const rewrites = [];
REWRITE.forEach(function (d) { if (d.re.test(addedOnly)) rewrites.push(d.label); });

let verdict = "SAFE";
if (!diffOk) { verdict = "UNKNOWN"; }
else if (hits.length > 0) { verdict = "DANGER"; }
else if (rewrites.length > 0) { verdict = "CAUTION"; }

const notes = String(rel.body || "(release notes unavailable)").slice(0, 6000);

let p = "";
p += "You are reviewing a self-hosted Docker upgrade BEFORE it is applied.\n\n";
p += "Container: " + up.container + "\n";
p += "Upgrade: " + up.oldTag + " -> " + up.newTag + "\n";
p += "Migration files changed: " + migFiles.length + "\n";
if (!diffOk) {
  p += "WARNING: the migration diff could NOT be fetched from GitHub, so NOTHING was inspected. The verdict is UNKNOWN, not safe.\n\n";
  p += "Write ONLY these two sections:\n";
  p += "WHY: one bullet stating the diff could not be fetched and this upgrade was NOT inspected.\n";
  p += "PRE-CHECK: none.\n\n";
  p += "Be terse. No preamble. Do not speculate about the contents of the upgrade.\n\n";
  p += "=== RELEASE NOTES ===\n" + notes;
} else {
  p += "A static scan already classified this as " + verdict;
  if (hits.length) { p += " because the new SQL contains: " + hits.join(", "); }
  p += ". Do NOT restate or re-grade the verdict.\n\n";
  p += "Write ONLY these two sections:\n";
  p += "WHY: at most 3 short bullets, each naming the specific migration file and what it does to existing data. Put any row deletion FIRST.\n";
  p += "PRE-CHECK: for EVERY statement that deletes rows conditionally or can RAISE EXCEPTION, give the exact SQL to COUNT the affected rows before upgrading. Row deletions first. If there are none, write none.\n\n";
  p += "Rules: judge ONLY from the SQL and notes below. Release notes routinely omit destructive behaviour, so trust the SQL over the prose. Do not speculate about anything not shown. Be terse. No preamble.\n\n";
  p += "=== RELEASE NOTES ===\n" + notes + "\n\n";
  p += "=== MIGRATION SQL ===\n" + sql;
}

return [{ json: {
  container: up.container,
  oldTag: up.oldTag,
  newTag: up.newTag,
  repo: up.repo,
  verdict: verdict,
  destructiveHits: hits,
  migrationCount: migFiles.length,
  migrationFiles: migFiles.map(function (f) { return f.filename; }),
  diffAvailable: diffOk,
  truncated: truncated,
  prompt: p
}}];

const raw = $input.first().json || {};
let text = "";
if (typeof raw.response === "string") {
  text = raw.response;
} else if (Array.isArray(raw.choices) && raw.choices.length > 0) {
  const msg = (raw.choices[0] || {}).message || {};
  text = msg.content || "";
} else {
  text = "(no LLM response)";
}
const t = $('Create Triage Prompt').first().json;
return [{ json: {
  container: t.container,
  oldTag: t.oldTag,
  newTag: t.newTag,
  repo: t.repo,
  verdict: t.verdict,
  destructiveHits: t.destructiveHits,
  migrationCount: t.migrationCount,
  migrationFiles: t.migrationFiles,
  diffAvailable: t.diffAvailable,
  truncated: t.truncated,
  llmText: text.trim()
}}];

const n = $input.first().json || {};
const cfg = $('Set WUD and LLM Configs').first().json || {};
const provider = String(cfg.notifyProvider || "ntfy").toLowerCase().trim();
const token = String(cfg.notifyAuthToken || "").trim();

function clip(s, max) {
  const v = String(s == null ? "" : s);
  if (v.length <= max) { return v; }
  return v.slice(0, max - 20) + "\n...[truncated]";
}

const tagFor = { DANGER: "rotating_light", CAUTION: "warning", SAFE: "white_check_mark", UNKNOWN: "grey_question" };
const prioFor = { DANGER: "5", CAUTION: "4", SAFE: "2", UNKNOWN: "3" };

const compareUrl = n.repo ? "https://github.com/" + n.repo + "/compare/" + n.oldTag + "..." + n.newTag : "(no GitHub repo detected)";

const summary = n.llmText + "\n\nStatic scan: " + n.verdict + (n.destructiveHits && n.destructiveHits.length ? " (" + n.destructiveHits.join(", ") + ")" : "") + "\nMigration files changed: " + n.migrationCount + "\nDiff fetched: " + n.diffAvailable + "\n" + compareUrl;

const title = n.verdict + ": " + n.container + " " + n.oldTag + " to " + n.newTag;

let url = "";
let headers = {};
let body = {};

if (token) { headers.Authorization = "Bearer " + token; }

if (provider === "ntfy") {
  url = String(cfg.notifyUrl || "").replace(/\/$/, "") + "/";
  body = { topic: cfg.notifyTopic, title: title, message: clip(summary, 3800), priority: Number(prioFor[n.verdict] || "3"), tags: [tagFor[n.verdict] || "information_source"] };
} else if (provider === "discord") {
  url = cfg.notifyUrl;
  body = { content: clip("**" + title + "**\n" + summary, 1900) };
} else if (provider === "slack") {
  url = cfg.notifyUrl;
  body = { text: clip("*" + title + "*\n" + summary, 3000) };
} else {
  url = cfg.notifyUrl;
  body = { title: title, message: summary, verdict: n.verdict, container: n.container, oldTag: n.oldTag, newTag: n.newTag, repo: n.repo };
}

return [{ json: { url: url, headers: headers, body: body } }];
